lemma complementary_mem_box (hi : ∀ {ψ χ}, ψ ➝ χ ∈ P → ψ ∈ P := by trivial) : □φ ∈ P⁻ → □φ ∈ P := by
  simp [complementary];
  intro h;
  rcases h with (h | ⟨ψ, hq, eq⟩);
  . assumption;
  . replace eq := Formula.complement.resort_box eq;
    subst eq;
    exact hi hq;

class ComplementaryClosed (P : Formulae α) (S : Formulae α) : Prop where
  subset : P ⊆ S⁻
