  (P_consis : Formulae.Consistent H P) (φ : Formula α)
  : Formulae.Consistent H (next H φ P) := by
  simp only [next];
  split;
  . simpa;
  . rename_i h;
    by_contra hC;
    have h₁ := Formulae.neg_provable_iff_insert_not_consistent (H := H) (P := P) (φ := φ) |>.mpr h;
