    have h₁ := Formulae.neg_provable_iff_insert_not_consistent (H := H) (P := P) (φ := φ) |>.mpr h;
    have h₂ := Formulae.neg_provable_iff_insert_not_consistent (H := H) (P := P) (φ := -φ) |>.mpr hC;
