noncomputable def next (φ : Formula α) (P : Formulae α) : Formulae α :=
  if Formulae.Consistent H (insert φ P) then insert φ P else insert (-φ) P

noncomputable def enum (P : Formulae α) : (List (Formula α)) → Formulae α
  | [] => P
