    exact ih;

@[simp] lemma enum_nil {P : Formulae α} : (P[[]]) = P := by simp [enum]

lemma enum_subset_step {l : List (Formula α)} : (P[l]) ⊆ (P[(ψ :: l)]) := by
  simp [enum, next];
  split <;> simp;

