  | nil => simp;
  | cons ψ qs ih => exact Set.Subset.trans ih $ by apply enum_subset_step;

lemma either {l : List (Formula α)} (hp : φ ∈ l) : φ ∈ P[l] ∨ -φ ∈ P[l] := by
  induction l with
  | nil => simp_all;
  | cons ψ qs ih =>
