  : ∃ P', P ⊆ P' ∧ Formulae.Consistent H P' ∧ P'.ComplementaryClosed S := by
  use exists_consistent_complementary_closed.enum H P S.toList;
  refine ⟨?_, ?_, ?_, ?_⟩;
